import java.util.*;
import java.io.*;

public class Main {
    // cap[j]: stock of DC j+1, dist[c][j]: distance from city c+1 to DC j+1,
    // requests[i] = {q, c} with c 1-based. Return the 1-based DC for each request, or -1.
    static int[] assign(long[] cap, long[][] dist, long[][] requests) {
        // Write your solution here
        int[] res = new int[requests.length];
        Arrays.fill(res, -1);
        return res;
    }

    public static void main(String[] args) throws IOException {
        StreamTokenizer in = new StreamTokenizer(new BufferedReader(new InputStreamReader(System.in)));
        in.nextToken();
        int D = (int) in.nval;
        in.nextToken();
        int C = (int) in.nval;
        in.nextToken();
        int R = (int) in.nval;
        long[] cap = new long[D];
        for (int j = 0; j < D; j++) {
            in.nextToken();
            cap[j] = (long) in.nval;
        }
        long[][] dist = new long[C][D];
        for (int c = 0; c < C; c++) {
            for (int j = 0; j < D; j++) {
                in.nextToken();
                dist[c][j] = (long) in.nval;
            }
        }
        long[][] requests = new long[R][2];
        for (int i = 0; i < R; i++) {
            in.nextToken();
            requests[i][0] = (long) in.nval;
            in.nextToken();
            requests[i][1] = (long) in.nval;
        }
        int[] res = assign(cap, dist, requests);
        StringBuilder sb = new StringBuilder();
        for (int x : res) sb.append(x).append("\n");
        System.out.print(sb);
    }
}
